export default function pickInvoiceMail({ emails }) {
  if (!Array.isArray(emails)) throw Error("Invalid IMAP search response");
  if (emails.length === 0) return { more: false, uid: 1 };
  const uid = emails[0]?.uid;
  if (!Number.isSafeInteger(uid) || uid < 1) throw Error("Invalid IMAP UID");
  return { more: true, uid };
}

