export default function inspectInvoiceMail({
  uid,
  actualUid,
  text,
  truncated,
  from,
  subject,
  date,
  attachments,
}) {
  if (actualUid !== uid || truncated) throw Error("Cannot inspect the complete email");
  if (typeof text !== "string") throw Error("Email has no plain text body");
  const match = text.toLowerCase().includes("invoice");
  if (!match) return { match: false, attachmentId: "unused", email: {} };
  const first = attachments?.[0];
  if (
    !first ||
    typeof first.attachmentId !== "string" ||
    !first.attachmentId ||
    !from?.email ||
    typeof subject !== "string" ||
    typeof date !== "string"
  )
    throw Error("Invoice email requires its first attachment, sender, subject and date");
  return {
    match: true,
    attachmentId: first.attachmentId,
    email: { from: from.email, subject, date },
  };
}

