export default function prepareInvoiceAttachment({ uid, attachmentId, actualUid, actualId, file }) {
  if (
    uid !== actualUid ||
    attachmentId !== actualId ||
    !file ||
    typeof file.name !== "string" ||
    !file.name ||
    typeof file.mimetype !== "string" ||
    !file.mimetype ||
    !/^https:\/\/[^\s/]+/.test(file.s3url || "")
  )
    throw Error("Invalid downloaded attachment");
  return {
    url: file.s3url,
    attachments: [{ filename: file.name, contentType: file.mimetype, contentUrl: file.s3url }],
  };
}

