export default async function enqueueReceipt({ url, modelId, apiKey }, context) {
  if (
    !/^https:\/\/[^\s/?#]+(?:[/?#][^\s]*)?$/i.test(url) ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(modelId) ||
    typeof apiKey !== "string" ||
    !apiKey.trim()
  )
    throw Error("Configure receipt URL, Mindee model ID and API key");
  const boundary = "openflow-mindee-form-7d1b8e6f";
  if (url.includes(boundary)) throw Error("Invalid URL");
  const body = `--${boundary}\r\nContent-Disposition: form-data; name="model_id"\r\n\r\n${modelId}\r\n--${boundary}\r\nContent-Disposition: form-data; name="url"\r\n\r\n${url}\r\n--${boundary}--\r\n`;
  const r = await context.fetch("https://api-v2.mindee.net/v2/products/extraction/enqueue", {
    method: "POST",
    headers: { Authorization: apiKey, "Content-Type": "multipart/form-data; boundary=" + boundary },
    body,
  });
  if (r.status !== 202) throw Error("Mindee enqueue failed or outcome unknown");
  const data = await r.json();
  if (!/^[0-9a-f-]{36}$/i.test(data?.job?.id ?? "") || data.job.model_id !== modelId)
    throw Error("Mindee returned an invalid job");
  return { jobId: data.job.id };
}

