export default async function pollReceipt({ jobId, apiKey, previousState }, context) {
  const attempt = (previousState?.jobId === jobId ? previousState.attempt : 0) + 1;
  if (attempt > 200) throw Error("Mindee did not finish within the polling window");
  if (!/^[0-9a-f-]{36}$/i.test(jobId) || typeof apiKey !== "string" || !apiKey.trim())
    throw Error("Invalid Mindee job or key");
  const r = await context.fetch(`https://api-v2.mindee.net/v2/jobs/${jobId}?redirect=false`, {
    headers: { Authorization: apiKey },
  });
  if (!r.ok) throw Error("Mindee job lookup failed");
  const data = await r.json(),
    job = data?.job;
  if (job?.id !== jobId) throw Error("Mindee job mismatch");
  if (job.status === "Failed") throw Error("Mindee receipt processing failed");
  if (job.status === "Processing")
    return {
      state: { jobId, attempt },
      ready: false,
      resultUrl: "https://api-v2.mindee.net/v2/products/extraction/results/unused",
    };
  if (
    job.status !== "Processed" ||
    !/^https:\/\/api-v2\.mindee\.net\/v2\/products\/extraction\/results\/[0-9a-f-]{36}$/i.test(
      job.result_url ?? "",
    )
  )
    throw Error("Invalid Mindee result URL");
  return { state: { jobId, attempt }, ready: true, resultUrl: job.result_url };
}

