export default async function readReceipt({ resultUrl, jobId, apiKey }, context) {
  if (
    !/^https:\/\/api-v2\.mindee\.net\/v2\/products\/extraction\/results\/[0-9a-f-]{36}$/i.test(
      resultUrl,
    )
  )
    throw Error("Invalid Mindee result URL");
  const r = await context.fetch(resultUrl, { headers: { Authorization: apiKey } });
  if (!r.ok) throw Error("Mindee result request failed");
  return { data: await r.json() };
}

