export default function invoiceAlert({ data, jobId, email }) {
  if (data?.inference?.job?.id !== jobId) throw Error("Mindee result job mismatch");
  const amount = data?.inference?.result?.fields?.total_amount?.value;
  if (typeof amount !== "number" || !Number.isFinite(amount))
    throw Error("Invoice total was not recognised");
  if (
    !email ||
    typeof email.from !== "string" ||
    typeof email.subject !== "string" ||
    typeof email.date !== "string"
  )
    throw Error("Invalid email details");
  return {
    high: amount > 1000,
    attachments: [
      {
        color: "#FFBF00",
        fields: [
          { short: true, title: "Amount", value: String(amount) },
          { short: false, title: "From", value: email.from },
          { short: true, title: "Subject", value: email.subject },
        ],
        footer: "*Date:* " + email.date,
      },
    ],
  };
}

