export default function invoiceSmtpConfirm({ accepted, rejected }) {
  if (!Array.isArray(accepted) || !accepted.length || !Array.isArray(rejected) || rejected.length)
    throw Error("SMTP did not accept the finance email");
  return { confirmed: true };
}
